def vm_pos_cashier():
    user = frappe.session.user
    row = frappe.db.get_value("Cashier Profile", user, ["company", "enabled"], as_dict=True)
    if row and row.get("company"):
        frappe.response["message"] = {"user": user, "company": row["company"], "enabled": row.get("enabled")}
        return
    comp = frappe.db.get_single_value("Global Defaults", "default_company")
    frappe.response["message"] = {"user": user, "company": comp, "enabled": 1}
vm_pos_cashier()
